package ar.didgetaller.core

/** Export vocabulary is independent of Android resources, with an explicit pair for every term. */
enum class WorkshopLanguage { ENGLISH, SPANISH;
    fun word(term:WorkshopTerm)=if(this==SPANISH)term.es else term.en
}

